"""Evaluation utilities (R13: labels are only used here)."""

import numpy as np
from sklearn.metrics import roc_auc_score


def auc(y_true, scores):
    """Rank-based ROC AUC; higher anomaly score means more anomalous (A8)."""
    y_true = np.asarray(y_true).ravel()
    scores = np.asarray(scores, dtype=np.float64).ravel()
    return float(roc_auc_score(y_true, scores))


def random_score_auc(y_true, seed=0):
    """Sanity check: AUC of pure noise must be ~0.5."""
    rng = np.random.default_rng(seed)
    return auc(y_true, rng.random(len(y_true)))


def aggregate(values):
    v = np.asarray(values, dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "values": [float(x) for x in v],
    }

